import React, { useMemo, useState } from "react";
import project from "@/store/project";
import { JSONSchemaCustom, SchemaTable } from "@/components/schema";
import { Button, Form, Message, Modal, Space, Tabs } from "@arco-design/web-react";
import { IconArrowFall, IconArrowRise, IconPlus } from "@arco-design/web-react/icon";
import { useObserver } from "mobx-react-lite";
import { AsyncButton, EditSchema } from "@/components/custom";
import TabPane from "@arco-design/web-react/es/Tabs/tab-pane";
import CustomVariableForm from "@/components/devs/customVariableForm";
import { FormGenerateContext } from "react-converter-code";
import { getFormats } from "@/environments/formats";

const Setting = () => {

    const schema = useMemo(() => {

        return {
            type: "object",
            properties: {
                name: {
                    title: "应用配置信息"
                },
                desc: {
                    title: "配置信息描述"
                }
            }
        } as JSONSchemaCustom;
    },[])

    return useObserver(() => {

        const [activeTab, setActiveTab] = useState("0");
        const [form] = Form.useForm();

        const content = useMemo(() => {
            return {
                formats: getFormats()
            }
        },[])

        return (
            <FormGenerateContext.Provider value={content}>
                <div className="flex justify-end mb-2 bg-white">
                    <Space>
                        <Button icon={<IconPlus />}
                            onClick={() => {
                                project.assignExtraInfo({
                                    customVariables: [
                                        ...project.extraInfo.customVariables,
                                        { type: "object", title: "新配置", properties: {} }
                                    ]
                                })
                                setActiveTab(String(project.extraInfo.customVariables.length - 1));
                            }}
                        >添加配置</Button>
                        <AsyncButton
                            type="primary"
                            onClick={() => {
                                return project.savaExtraInfo().then(() => {
                                    Message.success("配置保存成功")
                                })
                            }}
                        >
                            保存
                        </AsyncButton>
                    </Space>
                </div>
                <Form form={form} className="bg-white">
                    <Tabs activeTab={activeTab}
                        direction='vertical'
                        editable
                        onChange={setActiveTab}
                        type="card"
                        showAddButton={false}
                        onDeleteTab={(i) => {
                            project.extraInfo.customVariables.splice(Number(i),1);
                            setActiveTab("0")
                        }}
                    >
                        {project.extraInfo.customVariables.map((o, i) => {
                            return (
                                <Tabs.TabPane 
                                    title={(
                                        <div className="flex items-center">
                                            <Button size="mini"
                                                className="mr-2"
                                                shape='circle'
                                                type="primary"
                                                onClick={(e) => {
                                                    e.stopPropagation();
                                                    let result = [...project.extraInfo.customVariables];
                                                    if(result.length > 1){
                                                        if (i > 0) {
                                                            // 向上移动
                                                            const temp = result[i];
                                                            result[i] = result[i - 1];
                                                            result[i - 1] = temp;
                                                        } else {
                                                            // 向下移动
                                                            const temp = result[i];
                                                            result[i] = result[i + 1];
                                                            result[i + 1] = temp;
                                                        }
                                                    }
                                                    project.assignExtraInfo({
                                                        customVariables: result
                                                    })
                                                }}
                                            >
                                                {i > 0 ? <IconArrowRise /> : <IconArrowFall />}
                                            </Button>
                                            <span>{o.title}</span>
                                        </div>
                                    )}
                                    key={i}
                                    closable
                                >
                                    <div style={{ padding: 20 }}>
                                        <EditSchema
                                            value={project.extraInfo.customVariables[i]}
                                            onChange={(val) => {
                                                project.extraInfo.customVariables[i] = val;
                                            }}
                                            divProps={{ style: { marginBottom: 20 }}}
                                        />
                                        <CustomVariableForm
                                            form={form}
                                            schema={project.extraInfo.customVariables[i]}
                                        />
                                    </div>
                                </Tabs.TabPane>
                            )
                        })}
                    </Tabs>
                </Form>
            </FormGenerateContext.Provider>
        )
    })
}


export default Setting;